async function searchWeb(){const q=search.value.trim();if(!q){status.textContent='Digite o que procura para buscar novos ícones.';search.focus();return}const seq=++request;more.disabled=true;status.textContent='Buscando novos ícones…';webGrid.replaceChildren();webTitle.hidden=false;try{const query=translate[q.toLowerCase()]||q;const response=await fetch('https://api.iconify.design/search?prefix=lucide&limit=32&query='+encodeURIComponent(query),{signal:AbortSignal.timeout(12000)});if(!response.ok)throw Error();const data=await response.json();const ids=(data.icons||[]).filter(x=>/^lucide:[a-z0-9-]+$/.test(x)).slice(0,24);const results=await Promise.allSettled(ids.map(async id=>{const slug=id.split(':')[1],r=await fetch('https://api.iconify.design/lucide/'+slug+'.svg',{signal:AbortSignal.timeout(12000)});if(!r.ok)throw Error();const path=sanitize(await r.text());return {id,label:slug.replace(/-/g,' '),html:svg(path),path}}));if(seq!==request||!dialog.isConnected)return;const icons=results.filter(r=>r.status==='fulfilled').map(r=>r.value);icons.forEach(i=>tile(i,webGrid));status.textContent=icons.length?icons.length+' novos ícones. Selecione para importar e usar.':'Nenhum resultado. Tente outro termo.'}catch{if(seq===request)status.textContent='A busca online está indisponível. Você pode buscar na biblioteca ou importar um arquivo SVG.'}finally{if(seq===request)more.disabled=false}}
