function renderMostUsed(details){let bar=details.previousElementSibling;if(!bar?.classList.contains('most-used-icons')){bar=document.createElement('div');bar.className='most-used-icons';details.before(bar)}const scope=details.closest('.identity-pick,.location-sigla-field')||details.parentElement;const choices=[...scope.querySelectorAll('.icon-choice,.account-icon-dot')].filter(b=>!b.dataset.usedClone&&saved.used[fingerprint(b)]&&!saved.hidden.includes(fingerprint(b))&&(!details.closest('#job-edit')||!jobState.hidden.includes(fingerprint(b))));const unique=new Map();for(const b of choices)if(!unique.has(fingerprint(b)))unique.set(fingerprint(b),b);const ranked=[...unique.values()].sort((a,b)=>saved.used[fingerprint(b)].count-saved.used[fingerprint(a)].count||saved.used[fingerprint(b)].time-saved.used[fingerprint(a)].time).slice(0,6);const signature=ranked.map(b=>fingerprint(b)+':'+saved.used[fingerprint(b)].count).join(';');if(bar.dataset.signature===signature)return;bar.dataset.signature=signature;bar.replaceChildren();if(!ranked.length){bar.hidden=true;return}bar.hidden=false;const title=document.createElement('small');title.textContent='Mais usados';const gallery=document.createElement('div');gallery.className='icon-library';for(const original of ranked){const clone=original.cloneNode(true);clone.dataset.usedClone='yes';clone.hidden=false;clone.onclick=e=>{e.stopPropagation();original.click()};gallery.append(clone)}bar.append(title,gallery)}
document.addEventListener('click',e=>{const b=e.target.closest('.icon-choice,.account-icon-dot');if(!b||b.dataset.usedClone||b.closest('.icon-manager'))return;const id=fingerprint(b);const old=saved.used[id];saved.used[id]={count:(old?.count||0)+1,time:Date.now()};try{persist()}catch{}document.querySelectorAll('.identity-advanced').forEach(renderMostUsed)});
window.addEventListener('DOMContentLoaded',()=>{function enhance(){document.querySelectorAll('.identity-advanced').forEach(details=>{if(details.dataset.libraryManager)return;details.dataset.libraryManager='yes';if(details.closest('#job-edit')){jobState.custom.forEach(mountJobIcon);const launch=document.createElement('button');launch.type='button';launch.className='btn secondary job-manage-launch';launch.textContent='Gerenciar ícones';launch.onclick=()=>jobManager(details);details.before(launch);details.hidden=true;return}const b=document.createElement('button');b.type='button';b.className='btn secondary';b.textContent='Buscar, importar ou excluir ícones';b.onclick=manager;details.append(b)});applyHidden();document.querySelectorAll('.identity-advanced').forEach(renderMostUsed)}let queued=false;new MutationObserver(()=>{if(queued)return;queued=true;queueMicrotask(()=>{queued=false;enhance()})}).observe(document.body,{childList:true,subtree:true});enhance()});
